import {useMemo} from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'

import type {BuildId} from '../../../../../types'
import {notNull} from '../../../../../utils/guards'

import type {ArtifactDependenciesDownloadedArtifactsQuery} from './__generated__/ArtifactDependenciesDownloadedArtifactsQuery.graphql'

const downloadedArtifactsQuery = graphql`
  query ArtifactDependenciesDownloadedArtifactsQuery($buildLocator: String!, $skip: Boolean!) {
    build(buildLocator: $buildLocator) @skip(if: $skip) {
      downloadedArtifacts {
        downloadInfo {
          build {
            id
          }
          artifactInfo {
            path
          }
        }
      }
    }
  }
`

export const useDownloadedArtifacts = (from: BuildId, to?: BuildId | null) => {
  const {build} = useLazyLoadQuery<ArtifactDependenciesDownloadedArtifactsQuery>(
    downloadedArtifactsQuery,
    {
      buildLocator: `id:${to}`,
      skip: to == null,
    },
  )
  const {artifactInfo} =
    build?.downloadedArtifacts?.downloadInfo?.find(info => info.build?.id === from) ?? {}

  return useMemo(() => artifactInfo?.map(({path = ''}) => path).filter(notNull), [artifactInfo])
}
