import {memo} from 'react'

import type {BuildId} from '../../../../../types'
import {useDownloadedArtifacts} from '../../../../pages/BuildPage/DependenciesTab/ArtifactDependencies/ArtifactDependencies.utils'
import Files from '../../../Builds/Build/DownloadedDeliveredArtifacts/Files'

import styles from './ArtifactChangeDetails.module.css'

type Props = {
  className?: string
  from: BuildId
  to: BuildId
  withSmallPadding?: boolean
}

function ArtifactChangeDetails({from, to, withSmallPadding = false}: Props) {
  const files = useDownloadedArtifacts(from, to)
  return files != null ? (
    <div className={styles.wrapper}>
      <Files paths={files} buildId={from} compact={withSmallPadding === true} />
    </div>
  ) : null
}

export default memo(ArtifactChangeDetails)
