import type {ContentPanelProps} from '@jetbrains/teamcity-ui'
import {ContentPanel, ContentPanelContext} from '@jetbrains/teamcity-ui/dist/components'

import {useContentPanelContextValue} from './ContentPanel.hooks'

export default function ContentPanelContainer(props: ContentPanelProps) {
  const value = useContentPanelContextValue()
  return (
    <ContentPanelContext.Provider value={value}>
      <ContentPanel {...props} />
    </ContentPanelContext.Provider>
  )
}
