import plur from 'plur'
import {memo} from 'react'
import {graphql, useLazyLoadQuery} from 'react-relay'

import type {BuildId} from '../../../../types'

import type {ArtifactChangeFilesQuery} from './__generated__/ArtifactChangeFilesQuery.graphql'

const query = graphql`
  query ArtifactChangeFilesQuery($buildLocator: String!) {
    build(buildLocator: $buildLocator) {
      downloadedArtifacts {
        downloadInfo {
          build {
            id
          }
          artifactInfo {
            path
          }
        }
      }
    }
  }
`

type Props = {
  from: BuildId
  to: BuildId
}

function ArtifactChangeFiles({from, to}: Props) {
  const {build} = useLazyLoadQuery<ArtifactChangeFilesQuery>(query, {buildLocator: `id:${to}`})
  const countArtifacts = build?.downloadedArtifacts?.downloadInfo?.find(
    info => info.build?.id === from,
  )?.artifactInfo?.length

  return `${countArtifacts} ${plur('file', countArtifacts)}`
}

export default memo(ArtifactChangeFiles)
